acl_policies.default-ceiling:
# Allow an entity to inspect its own registration information
path "agent-registry/registration/entity_id/{{identity.entity.id}}" {
  capabilities = ["read"]
}

# Allow an entity to read the default policies
path "policy/default" {
  capabilities = ["read"]
}
path "policy/default-ceiling" {
  capabilities = ["read"]
}

acl_policies.eso-ewallet-agents:
# External Secrets Operator reader for namespace ewallet-agents (staged, opt-in).
# One shadow copy of the gateway client key; the live agentgateway-client-key Secret and
# the MCP credential releases are not managed through Vault.
path "ewallet/data/agent-platform/agentgateway-client-key" {
  capabilities = ["read"]
}

# token_no_default_policy removes these; ESO checks its login token and revokes it after use.
path "auth/token/lookup-self" {
  capabilities = ["read"]
}
path "auth/token/revoke-self" {
  capabilities = ["update"]
}

acl_policies.eso-ml-platform:
# External Secrets Operator reader for namespace ml-platform (SecretStore ml-platform/vault).
# Exactly the secrets that namespace's ExternalSecrets map, read only. No list, no metadata,
# so the reader cannot discover other paths. Add a path here only with its ExternalSecret.
path "ewallet/data/feature-api/feast-redis" {
  capabilities = ["read"]
}

# token_no_default_policy removes these; ESO checks its login token and revokes it after use.
path "auth/token/lookup-self" {
  capabilities = ["read"]
}
path "auth/token/revoke-self" {
  capabilities = ["update"]
}

acl_policies.eso-vault-rehearsal:
# GKE technical rehearsal only (docs/runbooks/edai2/VAULT_GKE_REHEARSAL.md): the ESO reader of the
# temporary namespace vault-rehearsal reads one synthetic entry. The path lies under feature-api/,
# which the existing secret-operator token may write, so the rehearsal seeds it exactly like the
# official campaign (put --token-file). The real feature-api/feast-redis is NOT readable here.
path "ewallet/data/feature-api/rehearsal-redis" {
  capabilities = ["read"]
}

# token_no_default_policy removes these; ESO checks its login token and revokes it after use.
path "auth/token/lookup-self" {
  capabilities = ["read"]
}
path "auth/token/revoke-self" {
  capabilities = ["update"]
}

acl_policies.feature-api:
# Exactly one secret, read only, separate from the Fraud API's path.
path "ewallet/data/feature-api/feast-redis" {
  capabilities = ["read"]
}

# token_no_default_policy removes this; the loader retires its token after reading.
path "auth/token/revoke-self" {
  capabilities = ["update"]
}

acl_policies.fraud-api:
# Exactly one secret, read only. No list, so a holder cannot discover other paths.
path "ewallet/data/fraud-api/feast-redis" {
  capabilities = ["read"]
}

# token_no_default_policy removes this; the loader retires its token after reading.
path "auth/token/revoke-self" {
  capabilities = ["update"]
}

acl_policies.root-generation:
# Vault 2.x authenticates root generation. This policy lets the owner's admin login
# (role vault-admin) start, read, cancel and feed a root-generation ceremony, and nothing
# else: no secrets, no policies, no roles. Completing the ceremony still needs 2 of the
# 3 unseal shares. Never attach it to ESO readers or application roles.
path "sys/generate-root/attempt" {
  capabilities = ["create", "read", "update", "delete"]
}
path "sys/generate-root/update" {
  capabilities = ["create", "update"]
}

acl_policies.secret-operator:
# Rotation by a human operator: write new versions and read metadata, never values.
path "ewallet/data/fraud-api/*" {
  capabilities = ["create", "update"]
}
path "ewallet/metadata/fraud-api/*" {
  capabilities = ["read", "list"]
}
path "ewallet/data/feature-api/*" {
  capabilities = ["create", "update"]
}
path "ewallet/metadata/feature-api/*" {
  capabilities = ["read", "list"]
}
path "ewallet/data/agent-platform/*" {
  capabilities = ["create", "update"]
}
path "ewallet/metadata/agent-platform/*" {
  capabilities = ["read", "list"]
}
